import java.util.*;

class Solution {
    public TreeNode searchBST(TreeNode root, int key) {
        TreeNode cur = root;
        while (cur != null && cur.val != key)
            cur = key < cur.val ? cur.left : cur.right;  // BST order picks one side
        return cur;
    }
}

